    cnt[key] = cnt.get(key, 0) + 1
    cid = f"X{key}-{cnt[key]:02d}"
    src = DEV if dep == "spxi.dev" else dtext(dep)
    ok = norm(q) in src
    if not ok: bad.append((cid, q[:70]))
